#include <stdexcept>
#include <vector>
#include "Jinja2Tools/EditorService.h"
namespace jinja2tools {EditorService::EditorService(const NppData&d):nppData_(d){}HWND EditorService::currentScintillaHandle()const{int i=0;SendMessage(nppData_._nppHandle,NPPM_GETCURRENTSCINTILLA,0,(LPARAM)&i);return i?nppData_._scintillaSecondHandle:nppData_._scintillaMainHandle;}std::string EditorService::getDocumentTextUtf8()const{auto h=currentScintillaHandle();auto n=(size_t)SendMessage(h,SCI_GETLENGTH,0,0);std::vector<char>b(n+1);SendMessage(h,SCI_GETTEXT,n+1,(LPARAM)b.data());return {b.data(),n};}EditorSelection EditorService::getSelection()const{auto h=currentScintillaHandle();return{(Sci_Position)SendMessage(h,SCI_GETSELECTIONSTART,0,0),(Sci_Position)SendMessage(h,SCI_GETSELECTIONEND,0,0)};}std::string EditorService::getSelectedTextUtf8()const{auto s=getSelection();if(s.end<=s.start)return{};std::vector<char>b((size_t)(s.end-s.start)+1);SendMessage(currentScintillaHandle(),SCI_GETSELTEXT,0,(LPARAM)b.data());return {b.data(),(size_t)(s.end-s.start)};}EditorSnapshot EditorService::captureSnapshot()const{auto h=currentScintillaHandle();return{getDocumentTextUtf8(),getSelection(),(Sci_Position)SendMessage(h,SCI_GETCURRENTPOS,0,0),(Sci_Position)SendMessage(h,SCI_GETFIRSTVISIBLELINE,0,0),(uint64_t)SendMessage(h,SCI_GETMODIFY,0,0)};}void EditorService::replaceDocument(std::string_view t,const EditorSnapshot&s){auto h=currentScintillaHandle();if(SendMessage(h,SCI_GETREADONLY,0,0))throw std::runtime_error("Document is read-only");SendMessage(h,SCI_BEGINUNDOACTION,0,0);SendMessage(h,SCI_SETTEXT,0,(LPARAM)std::string(t).c_str());SendMessage(h,SCI_ENDUNDOACTION,0,0);SendMessage(h,SCI_SETSEL,s.selection.start,s.selection.end);SendMessage(h,SCI_SETFIRSTVISIBLELINE,s.firstVisibleLine,0);}void EditorService::replaceSelection(std::string_view t,const EditorSnapshot&s){auto h=currentScintillaHandle();SendMessage(h,SCI_BEGINUNDOACTION,0,0);SendMessage(h,SCI_REPLACESEL,0,(LPARAM)std::string(t).c_str());SendMessage(h,SCI_ENDUNDOACTION,0,0);}void EditorService::clearDiagnostics(){SendMessage(currentScintillaHandle(),SCI_INDICATORCLEARRANGE,0,SendMessage(currentScintillaHandle(),SCI_GETLENGTH,0,0));}}
